SELECT id, location, budget, MIN(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_budget, COUNT(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_budget, AVG(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_budget, DENSE_RANK() OVER (PARTITION BY dept_name, location ORDER BY budget DESC) AS budget_dense_rank FROM departments WHERE location NOT IN ('New York', 'Bangkok');
